async ({method, path, headers, body, providerOrigin}) => {
              const origin = providerOrigin || location.origin;
              const target = new URL(path, location.href);
              if (location.origin !== origin || target.origin !== origin) {
                throw new Error('Canvas provider mismatch before fetch');
              }
              const opts = {method, credentials: 'include', headers: headers || {}};
              if (body != null && method !== 'GET' && method !== 'HEAD') {
                if (typeof body === 'string') opts.body = body;
                else {
                  opts.headers = Object.assign({'Content-Type': 'application/json'}, opts.headers);
                  opts.body = JSON.stringify(body);
                }
              }
              const r = await fetch(target.href, opts);
              if (new URL(r.url).origin !== origin || location.origin !== origin) {
                throw new Error('Canvas provider mismatch after fetch');
              }
              const text = await r.text();
              let json = null;
              try { json = JSON.parse(text); } catch (e) {}
              return {status: r.status, json, text: json ? null : text.slice(0, 4000)};
            }
